recipes.code:
{
  "inputs": [
    {
      "id": "zerodrop-api-key",
      "type": "promptString",
      "description": "ZeroDrop Workspace API key. Omit for free sandbox mode.",
      "password": true
    }
  ],
  "servers": {
    "zerodrop": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "zerodrop-mcp@0.1.2"
      ],
      "env": {
        "ZERODROP_API_KEY": "${input:zerodrop-api-key}",
        "ZERODROP_BASE_URL": "<zerodrop-base-url>"
      }
    }
  }
}
